"""
catalog_2fast.py
================
Cataloguing pipeline for 2FAST H5 experimental files.

Scans a root directory tree, parses each H5 file (SD and RG families),
classifies experiments, and exports a curated CSV catalogue ready for
GP pre-training and inter-session drift diagnostics.

Usage
-----
    python catalog_2fast.py --root /path/to/data --output catalogue.csv

Classification logic
--------------------
Filename pattern      | Flow condition                    | exp_type
----------------------|-----------------------------------|------------------
*_sample_*            | all flows == 2.8 µL/s (±tol)     | STANDARD
*_sample_*            | flows not all equal               | LHS
*_init_*              | any                               | BO_INIT
*_iter_*              | any                               | BO_ITER

n_pumps_free : number of pumps NOT fixed at 2.8 µL/s (relevant for BO sub-space)

Quality flags
-------------
- flag_low_abs   : final abs_max < ABS_MIN_THRESHOLD (likely failed experiment)
- flag_invalid   : parsing error or missing critical field
"""

import h5py
import numpy as np
import pandas as pd
import re
import argparse
import logging
from pathlib import Path
from dataclasses import dataclass, field, asdict
from typing import Optional

# ── Configuration ────────────────────────────────────────────────────────────

STANDARD_FLOW     = 2.8          # µL/s — nominal standard flow rate
STANDARD_TOL      = 0.15         # µL/s — tolerance for standard detection (±5%)
ABS_MIN_THRESHOLD = 0.05         # below this abs_max → flag_low_abs
N_PUMPS           = 5

logging.basicConfig(level=logging.INFO, format="%(levelname)s | %(message)s")
log = logging.getLogger(__name__)


# ── Data structure ────────────────────────────────────────────────────────────

@dataclass
class ExperimentRecord:
    # File identity
    filepath:       str  = ""
    filename:       str  = ""
    h5_family:      str  = ""       # file format
    # Experimental hierarchy
    session:        str  = ""       # e.g. S00 / S12
    manip:          str  = ""       # e.g. S00 / S12-M04
    sample_id:      str  = ""       # e.g. iter_2 / sample_3
    timestamp:      str  = ""
    # Classification
    exp_type:       str  = ""       # STANDARD / LHS / BO_INIT / BO_ITER
    n_pumps_free:   int  = -1       # 0-5
    # Flow rates (set points)
    Q1:             float = np.nan
    Q2:             float = np.nan
    Q3:             float = np.nan
    Q4:             float = np.nan
    Q5:             float = np.nan
    Q_total_set:    float = np.nan
    Q_total_meas:   float = np.nan
    # Spectral output
    lambda_max:     float = np.nan  # final λmax (nm)
    abs_max:        float = np.nan  # final absorbance at λmax
    # Kinetic features (from time-series)
    lmax_initial:   float = np.nan  # λmax at t=0 (first spectrum)
    lmax_final:     float = np.nan  # λmax at convergence (last spectrum)
    abs_initial:    float = np.nan  # abs_max at t=0
    abs_final:      float = np.nan  # abs_max at convergence
    n_spectra:      int   = -1      # number of spectra in time series
    # Quality
    flag_low_abs:   bool  = False
    flag_invalid:   bool  = False
    parse_error:    str   = ""


# ── H5 parsers ───────────────────────────────────────────────────────────────

def parse_sample(f: h5py.File, rec: ExperimentRecord) -> None:
    """Parse a sample H5 (format 2fast-sample 2.0)."""

    # Flow rates: commanded, fallback to measured
    if 'conditions/flow_set' in f:
        flows = f['conditions/flow_set'][()]
    elif 'conditions/flow_measured' in f:
        flows = f['conditions/flow_measured'][()]
    else:
        raise KeyError("No flow rate dataset found")

    rec.Q1, rec.Q2, rec.Q3, rec.Q4, rec.Q5 = flows
    rec.Q_total_set  = float(np.sum(flows))
    if 'conditions/flow_measured' in f:
        rec.Q_total_meas = float(np.sum(f['conditions/flow_measured'][()]))

    # fixed/varying pump masks
    if 'conditions/varying_pumps' in f:
        rec.n_pumps_free = int(np.sum(f['conditions/varying_pumps'][()]))

    # Metadata
    rec.timestamp = str(f['sample'].attrs.get('timestamp', ''))
    rec.session   = str(f['sample'].attrs.get('run', ''))

    # Spectral output
    rec.lambda_max = float(f['result'].attrs['lambda_max_nm'])
    rec.abs_max    = float(f['result'].attrs['extinction_max'])

    # Kinetic time series
    if 'spectra/lambda_max' in f:
        lmax_ts = f['spectra/lambda_max'][()]
        abs_ts  = f['spectra/extinction_max'][()]
        rec.lmax_initial = float(lmax_ts[0])
        rec.lmax_final   = float(lmax_ts[-1])
        rec.abs_initial  = float(abs_ts[0])
        rec.abs_final    = float(abs_ts[-1])
        rec.n_spectra    = len(lmax_ts)


# ── Classification helpers ────────────────────────────────────────────────────

def classify_experiment(filename: str, flows: np.ndarray) -> tuple[str, int]:
    """
    Returns (exp_type, n_pumps_free).

    exp_type  : STANDARD | LHS | BO_INIT | BO_ITER
    n_pumps_free : number of pumps not fixed at STANDARD_FLOW
    """
    stem = filename.lower()

    # Identify pumps at standard flow
    at_standard = np.abs(flows - STANDARD_FLOW) <= STANDARD_TOL
    n_at_std    = int(np.sum(at_standard))
    n_free      = N_PUMPS - n_at_std

    if '_iter_' in stem:
        exp_type = 'BO_ITER'
    elif '_init_' in stem:
        exp_type = 'BO_INIT'
    elif '_sample_' in stem:
        all_standard = np.all(at_standard)
        exp_type = 'STANDARD' if all_standard else 'LHS'
    else:
        exp_type = 'UNKNOWN'

    return exp_type, n_free


# Intermediate directory names that are structural (not manip identifiers)
_STRUCTURAL_DIRS = {"samples", "previous_samples", "data", "results", "output", "exports", "documents"}

def parse_session_manip(filepath: Path, metadata_session: str, family: str) -> tuple[str, str]:
    """
    Infer (session, manip) from directory structure and metadata.

    Handles two layouts:
      Standard layout : .../SESSION/MANIP/filename.h5
        e.g.  S00/S00/S00.h5
              S12/S12-M04/S12-M04_sample_3.h5

      SD standard layout (with intermediate structural subfolder):
        .../SESSION/MANIP/samples/filename.h5
        e.g.  S00/S00/samples/S00.h5

    Any directory name in _STRUCTURAL_DIRS is skipped when walking up
    the path to find the manip and session directories.
    """
    parts = filepath.parts

    # Keep only experiment-like directory names (starting with SD or RG).
    # This filters out structural dirs AND Windows system folders alike.
    _EXP_PREFIX = re.compile(r'^S\d', re.IGNORECASE)  # must start with SD/RG + digit
    candidates = [
        p for p in parts[:-1]
        if _EXP_PREFIX.match(p) and p.lower() not in _STRUCTURAL_DIRS
    ]

    if len(candidates) >= 2:
        manip   = candidates[-1]   # nearest non-structural parent
        session = candidates[-2]   # grandparent (skipping structural dirs)
    elif len(candidates) == 1:
        # Manip directly under root (no session folder) — infer session from manip name
        # e.g. S00 → S00  |  S00 → S00
        manip = candidates[0]
        match = re.match(r'^(S\d+)', manip)  # S00 or S00, not S00
        session = match.group(1) if match else manip
    elif len(parts) >= 3:
        manip   = parts[-2]
        session = parts[-3]
    else:
        # Last resort: parse from metadata experiment_name
        manip   = metadata_session
        match   = re.match(r'^(.+?)(?:_\d+)?$', metadata_session)
        session = match.group(1) if match else metadata_session

    return session, manip


# ── Main parser ───────────────────────────────────────────────────────────────

def parse_h5_file(filepath: Path) -> ExperimentRecord:
    """Parse a single H5 file and return an ExperimentRecord."""
    rec = ExperimentRecord()
    rec.filepath = str(filepath)
    rec.filename = filepath.stem

    try:
        rec.h5_family = "2.0"

        with h5py.File(filepath, 'r') as f:
            parse_sample(f, rec)

            rec.sample_id = str(f['sample'].attrs.get('sample_id', ''))

        # Classification
        flows = np.array([rec.Q1, rec.Q2, rec.Q3, rec.Q4, rec.Q5])
        rec.exp_type, n_free = classify_experiment(rec.filename, flows)

        # n_pumps_free: use explicit mask from RG if available, else infer
        if rec.n_pumps_free < 0:
            rec.n_pumps_free = n_free

        # Session / manip hierarchy
        rec.session, rec.manip = parse_session_manip(filepath, rec.session, rec.h5_family)

        # Quality flags
        rec.flag_low_abs = (rec.abs_max < ABS_MIN_THRESHOLD)

    except Exception as e:
        rec.flag_invalid = True
        rec.parse_error  = str(e)
        log.warning(f"Parse error on {filepath.name}: {e}")

    return rec


# ── Directory scanner ─────────────────────────────────────────────────────────

def scan_directory(root: Path) -> pd.DataFrame:
    """Recursively scan root for H5 files and build catalogue DataFrame."""
    h5_files = (list(root) if isinstance(root, (list, tuple))   # [vendored] explicit ordered list
                else sorted(root.rglob("*.h5")))
    # Exclude files inside previous_samples/ — they are copies of older
    # experiments reused as BO init points and would create duplicates
    h5_files = [f for f in h5_files
                if "previous_samples" not in f.parts]
    log.info(f"Found {len(h5_files)} H5 files under "   # [vendored] do not print the whole list
             f"{'the explicit list' if isinstance(root, (list, tuple)) else root} "
             f"(previous_samples/ excluded)")

    records = []
    for i, fp in enumerate(h5_files):
        if i % 50 == 0:
            log.info(f"  Parsing {i}/{len(h5_files)} ...")
        rec = parse_h5_file(fp)
        records.append(asdict(rec))

    df = pd.DataFrame(records)

    # Summary statistics
    log.info("\n=== Catalogue summary ===")
    log.info(f"Total files   : {len(df)}")
    log.info(f"Invalid files : {df['flag_invalid'].sum()}")
    log.info(f"Low abs files : {df['flag_low_abs'].sum()}")
    log.info("\nBy exp_type:")
    log.info(df['exp_type'].value_counts().to_string())
    log.info("\nBy h5_family:")
    log.info(df['h5_family'].value_counts().to_string())
    log.info("\nBy session (top 10):")
    log.info(df['session'].value_counts().head(10).to_string())

    return df


# ── CLI ───────────────────────────────────────────────────────────────────────

def main():
    parser = argparse.ArgumentParser(description="Catalogue 2FAST H5 experimental files.")
    parser.add_argument('--root',   required=True, help="Root directory containing H5 files")
    parser.add_argument('--output', default='catalogue.csv', help="Output CSV path")
    parser.add_argument('--debug',  action='store_true', help="Verbose debug logging")
    args = parser.parse_args()

    if args.debug:
        logging.getLogger().setLevel(logging.DEBUG)

    root = Path(args.root)
    if not root.exists():
        log.error(f"Root directory not found: {root}")
        return

    df = scan_directory(root)
    df.to_csv(args.output, index=False)
    log.info(f"\nCatalogue saved → {args.output}")

    # Quick validity report
    valid = df[~df['flag_invalid']]
    log.info(f"\nValid records  : {len(valid)}")
    log.info(f"λmax range     : {valid['lambda_max'].min():.1f} – {valid['lambda_max'].max():.1f} nm")
    log.info(f"abs_max range  : {valid['abs_max'].min():.4f} – {valid['abs_max'].max():.4f}")


if __name__ == '__main__':
    main()
